-- "Always fix backup component paths and insert missing components" block —
-- originally ran unconditionally on every boot (guarded only by
-- backup_components existing, which 000-baseline.sql now guarantees).
-- Every statement here is naturally idempotent (UPDATE / INSERT OR IGNORE),
-- so folding it into a run-once migration changes nothing observable.
UPDATE backup_components SET source_paths_json = '["docker://quox-auth:/var/lib/quox/uploads/"]' WHERE component_key = 'org_logos';
UPDATE backup_components SET source_paths_json = '["/etc/ssl/quox/", "certs/"]' WHERE component_key = 'ssl_certs';
UPDATE backup_components SET source_paths_json = '["docker://quox-qdrant:/qdrant/storage/"]' WHERE component_key = 'qdrant_vectors';

